const ids = ['2056995','2309229','2259203','2006231','1541165','2242828','2401261','2401246','2449611','2106856','1465223','2475501'];
const form = document.getElementById('editform');
ids.forEach(id => {
  if (!document.getElementById('attendee_'+id)) {
    const hidden = document.createElement('input');
    hidden.type = 'hidden'; hidden.name = 'attendee_'+id; hidden.value = 'off';
    const cb = document.createElement('input');
    cb.type = 'checkbox'; cb.id = 'attendee_'+id; cb.name = 'attendee_'+id;
    form.appendChild(hidden);
    form.appendChild(cb);
    cb.checked = true;
    cb.dispatchEvent(new Event('change', {bubbles:true}));
    cb.dispatchEvent(new Event('click', {bubbles:true}));
  }
});
